// The resumable upload of MOD12-P2-T02 against a scripted store: the session is opened with the headers OP-19
// gave, the file goes in pieces with Content-Range, and a break resumes from the byte the store holds. The real
// store is NOT VERIFIED (upload.ts). Generated bytes only.
import { expect, test } from 'vitest';
import { resumableUpload, UploadError } from '../src/upload';
import type { FetchFn } from '../src/upload';

const ADDRESS = { upload_url: 'https://store.example.test/start', upload_headers: { 'content-type': 'application/pdf', 'x-goog-resumable': 'start' } };
const SESSION = 'https://store.example.test/session-1';

interface Seen {
  url: string;
  method: string;
  headers: Record<string, string>;
  bytes: number;
}

// A store that keeps what arrives. `script` can break or refuse a numbered request.
function store(size: number, script: Record<number, 'throw' | number> = {}) {
  const seen: Seen[] = [];
  let held = 0;
  const fetchFn: FetchFn = async (url, init) => {
    const headers = (init.headers ?? {}) as Record<string, string>;
    const body = init.body as Blob | undefined;
    seen.push({ url, method: String(init.method), headers, bytes: body?.size ?? 0 });
    const step = script[seen.length];
    if (step === 'throw') throw new TypeError('network');
    if (typeof step === 'number') return new Response(null, { status: step });
    if (init.method === 'POST') return new Response(null, { status: 201, headers: { Location: SESSION } });
    const range = headers['content-range'];
    if (range.startsWith('bytes */')) {
      return held >= size ? new Response(null, { status: 200 }) : new Response(null, { status: 308, headers: held ? { Range: `bytes=0-${held - 1}` } : {} });
    }
    const [, from] = /^bytes (\d+)-/.exec(range)!;
    if (Number(from) !== held) return new Response(null, { status: 400 });
    held += body!.size;
    return held >= size ? new Response(null, { status: 200 }) : new Response(null, { status: 308, headers: { Range: `bytes=0-${held - 1}` } });
  };
  return { fetchFn, seen, held: () => held };
}

const file = (size: number) => new Blob([new Uint8Array(size)], { type: 'application/pdf' });

test('the session opens with the given headers and no credentials, and the file goes in ranged pieces', async () => {
  const { fetchFn, seen, held } = store(10);
  const progress: number[] = [];
  await resumableUpload(fetchFn, ADDRESS, file(10), (sent) => progress.push(sent), { chunkBytes: 4 });
  expect(seen[0]).toMatchObject({ url: ADDRESS.upload_url, method: 'POST', headers: ADDRESS.upload_headers, bytes: 0 });
  expect(seen.slice(1).map((s) => [s.url, s.method, s.headers['content-range'], s.bytes])).toEqual([
    [SESSION, 'PUT', 'bytes 0-3/10', 4],
    [SESSION, 'PUT', 'bytes 4-7/10', 4],
    [SESSION, 'PUT', 'bytes 8-9/10', 2],
  ]);
  expect(held()).toBe(10);
  expect(progress).toEqual([4, 8, 10]);
});

test('FR-ADMIN-007: after a lost connection the upload asks what the store holds and continues from there', async () => {
  const { fetchFn, seen, held } = store(10, { 3: 'throw' });
  await resumableUpload(fetchFn, ADDRESS, file(10), undefined, { chunkBytes: 4 });
  const ranges = seen.slice(1).map((s) => s.headers['content-range']);
  expect(ranges).toEqual(['bytes 0-3/10', 'bytes 4-7/10', 'bytes */10', 'bytes 4-7/10', 'bytes 8-9/10']);
  expect(held()).toBe(10);
});

test('a server error is treated as a break and resumed', async () => {
  const { fetchFn, held } = store(10, { 2: 503 });
  await resumableUpload(fetchFn, ADDRESS, file(10), undefined, { chunkBytes: 4 });
  expect(held()).toBe(10);
});

test('a refusal from the store stops the upload as refused', async () => {
  const { fetchFn } = store(10, { 2: 403 });
  await expect(resumableUpload(fetchFn, ADDRESS, file(10), undefined, { chunkBytes: 4 })).rejects.toMatchObject({ kind: 'refused' });
});

test('a session that cannot be opened stops as start, and so does a reply with no session address', async () => {
  await expect(resumableUpload(store(10, { 1: 'throw' }).fetchFn, ADDRESS, file(10))).rejects.toMatchObject({ kind: 'start' });
  await expect(resumableUpload(store(10, { 1: 403 }).fetchFn, ADDRESS, file(10))).rejects.toMatchObject({ kind: 'start' });
  const noLocation: FetchFn = async () => new Response(null, { status: 201 });
  await expect(resumableUpload(noLocation, ADDRESS, file(10))).rejects.toBeInstanceOf(UploadError);
});

test('a connection that keeps breaking stops after the resume limit, as broken', async () => {
  const script = Object.fromEntries(Array.from({ length: 30 }, (_, i) => [i + 2, 'throw' as const]));
  const { fetchFn } = store(10, script);
  await expect(resumableUpload(fetchFn, ADDRESS, file(10), undefined, { chunkBytes: 4, maxResumes: 3 })).rejects.toMatchObject({ kind: 'broken' });
});

test('a store that already holds the whole file after a break finishes without sending it again', async () => {
  const { fetchFn, seen } = store(4, { 2: 'throw' });
  // The first piece never reported back; pretend the store kept it by answering the status check as complete.
  let first = true;
  const wrapped: FetchFn = async (url, init) => {
    const headers = (init.headers ?? {}) as Record<string, string>;
    if (headers['content-range'] === 'bytes */4' && first) {
      first = false;
      seen.push({ url, method: 'PUT', headers, bytes: 0 });
      return new Response(null, { status: 200 });
    }
    return fetchFn(url, init);
  };
  await resumableUpload(wrapped, ADDRESS, file(4), undefined, { chunkBytes: 4 });
  expect(seen.map((s) => s.headers['content-range'] ?? 'open')).toEqual(['open', 'bytes 0-3/4', 'bytes */4']);
});
